beginning.embedded_functions:
/**
 * Bounded search for the RFC1867 upload-progress field name inside the HTTP
 * payload. http.p_payload is not NUL-terminated: scan at most len bytes.
 * The multipart body usually sits in a later TCP segment than the request
 * headers, so event 2 scans the payload of a packet tied to event 1's flow.
 * Returns 1 when "PHP_SESSION_UPLOAD_PROGRESS" is present, 0 otherwise.
 */
static inline int em_has_upload_progress( const void *payload, double len ){
    const char *p = payload, needle[] = "PHP_SESSION_UPLOAD_PROGRESS";
    size_t i, n = sizeof( needle ) - 1, l;
    if( payload == NULL || len <= 0 ) return 0;
    l = (size_t) len;
    if( l < n ) return 0;
    for( i = 0; i + n <= l; i++ )
        if( memcmp( p + i, needle, n ) == 0 ) return 1;
    return 0;
}
